const out = [];
for (const item of items) {
  const m = item.json;
  const subject = (m.subject || '').trim();
  const body = (m.textPlain || m.textHtml || '').toString();
  const to = (m.to || '').toString();
  const from = (m.from || '').toString();

  // Exkludera sannolikt spam/systemmail
  const isAuto = /(noreply|do-not-reply|mailer-daemon|automatiskt svar)/i.test(from + ' ' + subject);
  if (isAuto) continue;

  const hasQuestion = /[?]|kan du|kan ni|behöver|vill du|vill ni|återkoppla|återkom/i.test(subject + ' ' + body);
  if (!hasQuestion) continue;

  const isFortnoxOffer = /(fortnox|offert|quote)/i.test(subject + ' ' + body);

  out.push({
    json: {
      source: 'sent',
      messageId: m.messageId || m.id || '',
      threadKey: ((subject || '').replace(/^\s*(re|sv|fw|fwd):\s*/ig, '').trim().toLowerCase()) + '|' + to.toLowerCase(),
      subject,
      contact: to,
      from,
      date: m.date || new Date().toISOString(),
      category: isFortnoxOffer ? 'fortnox_offert' : 'utgaende_fraga',
      questionSnippet: (body || '').replace(/\s+/g, ' ').slice(0, 280),
      waitingFor: 'kund'
    }
  });
}
return out;

const out = [];
for (const item of items) {
  const m = item.json;
  const subject = (m.subject || '').trim();
  const body = (m.textPlain || m.textHtml || '').toString();
  const from = (m.from || '').toString();

  // Filter: fokus på riktiga personmail till dig, inte spam/auto
  const isAuto = /(noreply|do-not-reply|mailer-daemon|automatiskt svar|out of office)/i.test(from + ' ' + subject);
  if (isAuto) continue;

  const hasQuestion = /[?]|kan du|kan ni|behöver|vill du|vill ni|återkoppla|när kan/i.test(subject + ' ' + body);

  out.push({
    json: {
      source: 'inbox',
      messageId: m.messageId || m.id || '',
      inReplyTo: m.inReplyTo || '',
      threadKey: ((subject || '').replace(/^\s*(re|sv|fw|fwd):\s*/ig, '').trim().toLowerCase()),
      subject,
      contact: from,
      date: m.date || new Date().toISOString(),
      hasQuestion,
      questionSnippet: (body || '').replace(/\s+/g, ' ').slice(0, 280)
    }
  });
}
return out;

const state = getWorkflowStaticData('global');
state.pendingFromCustomer = state.pendingFromCustomer || {};
state.pendingFromMe = state.pendingFromMe || {};
state.answered = state.answered || {};
state.lastLunchSummaryDate = state.lastLunchSummaryDate || '';

for (const item of items) {
  const m = item.json;

  if (m.source === 'sent') {
    state.pendingFromCustomer[m.threadKey] = {
      contact: m.contact,
      subject: m.subject,
      category: m.category,
      askedAt: m.date,
      questionSnippet: m.questionSnippet,
      status: 'vantar_pa_svar'
    };
    continue;
  }

  if (m.source === 'inbox') {
    // Inkommande svar som matchar tidigare utgående fråga
    const matchKey = Object.keys(state.pendingFromCustomer).find(k => k.startsWith(m.threadKey + '|') || k.includes(m.threadKey));
    if (matchKey) {
      state.pendingFromCustomer[matchKey].status = 'besvarad';
      state.pendingFromCustomer[matchKey].answeredAt = m.date;
      state.answered[matchKey] = state.pendingFromCustomer[matchKey];
      delete state.pendingFromCustomer[matchKey];
      continue;
    }

    // Fråga från kund som väntar på svar från dig
    if (m.hasQuestion) {
      const key = `${m.threadKey}|${m.contact.toLowerCase()}`;
      state.pendingFromMe[key] = {
        contact: m.contact,
        subject: m.subject,
        askedAt: m.date,
        questionSnippet: m.questionSnippet,
        status: 'kund_vantar_pa_mig'
      };
    }
  }
}

const pendingCustomer = Object.entries(state.pendingFromCustomer).map(([key, v]) => ({ key, ...v }));
const pendingMe = Object.entries(state.pendingFromMe).map(([key, v]) => ({ key, ...v }));

const todoLines = [];
todoLines.push(`# Mail-uppföljning ${new Date().toISOString()}`);
todoLines.push('');
todoLines.push('## Jag väntar på svar från kund');
for (const p of pendingCustomer) {
  const tag = p.category === 'fortnox_offert' ? '[FORTNOX/OFFERT]' : '[UTGÅENDE FRÅGA]';
  todoLines.push(`- ${tag} ${p.contact} | ${p.subject} | fråga: ${p.questionSnippet}`);
}
if (!pendingCustomer.length) todoLines.push('- Inga öppna kundsvar.');

todoLines.push('');
todoLines.push('## Kunder väntar på svar från mig');
for (const p of pendingMe) {
  todoLines.push(`- ${p.contact} | ${p.subject} | väntar på: ${p.questionSnippet}`);
}
if (!pendingMe.length) todoLines.push('- Inga öppna frågor till mig.');

const dashboard = {
  generatedAt: new Date().toISOString(),
  pendingFromCustomer: pendingCustomer,
  pendingFromMe: pendingMe
};

const now = new Date();
const today = now.toISOString().slice(0, 10);
const isLunchWindow = now.getHours() === 12;
const shouldSendLunchSummary = isLunchWindow && state.lastLunchSummaryDate !== today;
if (shouldSendLunchSummary) state.lastLunchSummaryDate = today;

const mailSummary = [
  `Lunchrapport ${today}`,
  '',
  'Jag väntar på svar från kund:',
  ...pendingCustomer.map(p => `- ${p.contact}: ${p.subject}`),
  '',
  'Kunder väntar på svar från mig:',
  ...pendingMe.map(p => `- ${p.contact}: ${p.subject} (väntar på: ${p.questionSnippet})`)
].join('\n');

return [{
  json: {
    shouldSendLunchSummary,
    todoText: todoLines.join('\n'),
    dashboardJson: JSON.stringify(dashboard, null, 2),
    mailSummary
  }
}];
